/**
 * Autogenerated sidebars.
 *
 *   "sidebar": "auto"
 *   "sidebar": [{ "group": "Guides", "autogenerate": "guides" }]
 *   "sidebar": [{ "group": "Guides", "autogenerate": { "directory": "guides", "collapsed": true } }]
 *
 * expandSidebar() turns any of these into the explicit shape the rest of the
 * tool already understands: [{ group, pages: [id | { group, pages }] }].
 * Pure apart from reading the docs tree through a "source" (fs or git tree).
 */
import path from 'path';
import fs from 'fs-extra';
import { parseFrontmatter } from './frontmatter.js';
import { applyNavigation, normalizeDir, isHiddenMeta, slugify, collectIds } from './navigation.js';

const PRIORITY_NAMES = new Set(['index', 'introduction', 'overview']);

/** Title-case a directory name: "getting-started" -> "Getting Started". */
export function titleCase(name) {
  return String(name).replace(/[-_]+/g, ' ').trim().replace(/\b\w/g, (c) => c.toUpperCase());
}

/** True if a sidebar value contains anything expandSidebar must expand. */
export function hasAutogenerate(sidebar) {
  if (sidebar === 'auto') return true;
  if (!Array.isArray(sidebar)) return false;
  const walk = (items) => items.some((it) => it && typeof it === 'object' && (
    it.autogenerate !== undefined || (Array.isArray(it.pages) && walk(it.pages))
  ));
  return walk(sidebar);
}

/** True if any tab needs expansion ("sidebar": "auto", a path-only tab, or autogenerate groups). */
export function hasTabAutogenerate(tabs) {
  if (!Array.isArray(tabs)) return false;
  return tabs.some((t) => t && typeof t === 'object' && !t.href
    && (t.sidebar === 'auto' || (t.sidebar === undefined && typeof t.path === 'string' && t.path.trim() !== '') || hasAutogenerate(t.sidebar)));
}

// ─── Sources ──────────────────────────────────────────────────────────────────
// A source exposes list(relDir) -> [{ name, isDir }] and read(relPath) -> string|null,
// with paths relative to the docs root (posix).

export function createFsSource(docsDir) {
  return {
    async list(rel) {
      try {
        const entries = await fs.readdir(path.join(docsDir, rel), { withFileTypes: true });
        return entries
          .filter((e) => e.isDirectory() || e.isFile())
          .map((e) => ({ name: e.name, isDir: e.isDirectory() }));
      } catch { return []; }
    },
    async read(rel) {
      try { return await fs.readFile(path.join(docsDir, rel), 'utf8'); } catch { return null; }
    },
  };
}

/** Source backed by a flat list of docs-relative file paths (e.g. a git tree). */
export function createFileListSource(files, readFn) {
  const dirs = new Map();
  const add = (dir, name, isDir) => {
    if (!dirs.has(dir)) dirs.set(dir, new Map());
    dirs.get(dir).set(name, isDir);
  };
  for (const f of files) {
    const parts = f.split('/');
    for (let i = 0; i < parts.length; i++) {
      add(parts.slice(0, i).join('/'), parts[i], i < parts.length - 1);
    }
  }
  return {
    async list(rel) {
      const m = dirs.get(rel.replace(/\/+$/, ''));
      return m ? [...m].map(([name, isDir]) => ({ name, isDir })) : [];
    },
    read: readFn,
  };
}

// ─── Scanning ─────────────────────────────────────────────────────────────────

function normalizeDirectory(dir) {
  const norm = path.posix.normalize(String(dir ?? '').replace(/\\/g, '/').replace(/^\/+|\/+$/g, '') || '.');
  if (norm === '.') return '';
  if (norm === '..' || norm.startsWith('../')) return null;
  return norm;
}

function rank(node) {
  if (node.kind === 'group') return 2;
  return PRIORITY_NAMES.has(node.name) ? 0 : 1;
}

function compareNodes(a, b) {
  const pa = a.position ?? Infinity;
  const pb = b.position ?? Infinity;
  if (pa !== pb) return pa < pb ? -1 : 1;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  return a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
}

function toNumber(v) {
  return typeof v === 'number' && Number.isFinite(v) ? v : undefined;
}

async function readCategory(source, relDir, ctx) {
  const raw = await source.read(relDir ? `${relDir}/_category.json` : '_category.json');
  if (raw == null) return {};
  try {
    const data = JSON.parse(raw);
    return data && typeof data === 'object' ? data : {};
  } catch {
    ctx.warn(`Invalid JSON in docs/${relDir ? relDir + '/' : ''}_category.json — ignored`);
    return {};
  }
}

/** Scan one directory: returns sorted nodes (pages and non-empty subgroups). */
async function scanDir(source, relDir, ctx) {
  const entries = await source.list(relDir);
  const nodes = [];
  const join = (n) => (relDir ? `${relDir}/${n}` : n);

  await Promise.all(entries.map(async (e) => {
    if (e.name.startsWith('_') || e.name.startsWith('.') || e.name === 'node_modules') return;
    if (e.isDir) {
      const children = await scanDir(source, join(e.name), ctx);
      if (!children.length) return;
      const cat = await readCategory(source, join(e.name), ctx);
      nodes.push({
        kind: 'group',
        name: e.name,
        position: toNumber(cat.position),
        label: typeof cat.label === 'string' && cat.label.trim() ? cat.label : titleCase(e.name),
        collapsed: typeof cat.collapsed === 'boolean' ? cat.collapsed
          : typeof cat.expanded === 'boolean' ? !cat.expanded : undefined,
        extras: categoryExtras(cat),
        children,
      });
      return;
    }
    if (!e.name.endsWith('.md')) return;
    const base = e.name.slice(0, -3);
    const id = join(base);
    if (ctx.exclude.has(id)) return;
    let fm = {};
    try { fm = parseFrontmatter(await source.read(join(e.name)) || '').data || {}; } catch { /* validate reports */ }
    if (fm.sidebar === false) return;
    nodes.push({ kind: 'page', name: base, id, position: toNumber(fm.sidebar_position), hidden: isHiddenMeta(fm) });
  }));

  return nodes.sort(compareNodes);
}

/** Group metadata a _category.json may carry besides label/position/collapsed. */
function categoryExtras(cat) {
  const out = {};
  for (const k of ['icon', 'tag', 'availability']) {
    if (typeof cat[k] === 'string' && cat[k].trim()) out[k] = cat[k].trim();
  }
  if (cat.hidden === true) out.hidden = true;
  return out;
}

function nodesToPages(nodes, ctx, collapsed) {
  return nodes.map((n) => {
    if (n.kind === 'page') return n.hidden ? { id: n.id, hidden: true } : n.id;
    const g = { group: n.label, ...(n.extras || {}), pages: nodesToPages(n.children, ctx, collapsed) };
    const c = n.collapsed ?? collapsed;
    if (typeof c === 'boolean') g.collapsed = c;
    return g;
  });
}

function collectExplicitIds(items, set = new Set()) {
  for (const it of items || []) {
    if (typeof it === 'string') set.add(it);
    else if (it && typeof it === 'object') {
      if (it.id) set.add(it.id);
      if (Array.isArray(it.pages)) collectExplicitIds(it.pages, set);
    }
  }
  return set;
}

async function expandGroupLike(item, source, ctx) {
  const { autogenerate, ...rest } = item;
  const hasExplicit = Array.isArray(rest.pages);
  const explicit = hasExplicit ? await expandPages(rest.pages, source, ctx) : [];

  if (autogenerate === undefined) return { ...rest, pages: explicit };

  const opts = typeof autogenerate === 'string' ? { directory: autogenerate } : (autogenerate || {});
  const dir = normalizeDirectory(opts.directory);
  const label = rest.group || '';
  if (dir === null || typeof opts.directory !== 'string') {
    ctx.warn(`Sidebar group "${label}": invalid autogenerate directory ${JSON.stringify(opts.directory)}`);
    return { ...rest, pages: explicit };
  }
  const nodes = await scanDir(source, dir, ctx);
  if (!nodes.length) ctx.warn(`Sidebar group "${label}": autogenerate directory "docs/${dir}" has no pages`);
  const out = { ...rest, pages: [...explicit, ...nodesToPages(nodes, ctx, opts.collapsed)] };
  if (typeof opts.collapsed === 'boolean') out.collapsed = opts.collapsed;
  return out;
}

async function expandPages(pages, source, ctx) {
  const out = [];
  for (const it of pages) {
    if (it && typeof it === 'object' && !it.id && (it.autogenerate !== undefined || Array.isArray(it.pages))) {
      out.push(await expandGroupLike(it, source, ctx));
    } else {
      out.push(it);
    }
  }
  return out;
}

async function expandAuto(source, ctx, siteName, rootDir = '') {
  const nodes = await scanDir(source, rootDir, ctx);
  const groups = [];
  const rootPages = nodes.filter((n) => n.kind === 'page');
  if (rootPages.length) groups.push({ group: siteName || 'Docs', pages: nodesToPages(rootPages, ctx) });
  for (const n of nodes.filter((x) => x.kind === 'group')) {
    const g = { group: n.label, ...(n.extras || {}), pages: nodesToPages(n.children, ctx) };
    if (typeof n.collapsed === 'boolean') g.collapsed = n.collapsed;
    groups.push(g);
  }
  return groups;
}

/**
 * Expand a sidebar value ("auto" or an array that may contain autogenerate
 * groups) into a fully explicit sidebar array. Returns non-expandable values
 * unchanged.
 */
export async function expandSidebarValue(sidebar, source, { siteName = null, warn = () => {} } = {}) {
  if (!hasAutogenerate(sidebar)) return sidebar;
  const ctx = { warn, exclude: new Set() };
  if (sidebar === 'auto') return expandAuto(source, ctx, siteName);
  ctx.exclude = collectExplicitIds(sidebar);
  return expandPages(sidebar, source, ctx);
}

/**
 * Expand the sidebar of every tab: "auto" (optionally scoped to the tab's `path`), a tab with
 * only a `path`, or explicit sidebars containing autogenerate groups. Returns a new array.
 */
export async function expandTabsValue(tabs, source, { siteName = null, warn = () => {} } = {}) {
  if (!Array.isArray(tabs)) return tabs;
  const explicit = new Set();
  for (const t of tabs) {
    if (t && Array.isArray(t.sidebar)) collectExplicitIds(t.sidebar, explicit);
  }
  const out = [];
  for (const t of tabs) {
    if (!t || typeof t !== 'object' || t.href) { out.push(t); continue; }
    const ctx = { warn, exclude: explicit };
    const label = String(t.tab ?? t.label ?? t.title ?? t.name ?? '');
    if (t.sidebar === 'auto' || (t.sidebar === undefined && typeof t.path === 'string' && t.path.trim())) {
      const dir = normalizeDir(t.path);
      if (typeof t.path === 'string' && t.path.trim() && !dir) warn(`Tab "${label}": invalid path ${JSON.stringify(t.path)}`);
      const groups = await expandAuto(source, ctx, label || siteName, dir);
      if (!groups.length) warn(`Tab "${label}": autogenerate found no pages${dir ? ` in docs/${dir}` : ''}`);
      out.push({ ...t, sidebar: groups });
    } else if (hasAutogenerate(t.sidebar)) {
      out.push({ ...t, sidebar: await expandPages(t.sidebar, source, ctx) });
    } else {
      out.push(t);
    }
  }
  return out;
}

// ─── Hidden pages ─────────────────────────────────────────────────────────────

async function listMarkdown(source, relDir = '', out = []) {
  for (const e of await source.list(relDir)) {
    if (e.name.startsWith('_') || e.name.startsWith('.') || e.name === 'node_modules') continue;
    const rel = relDir ? `${relDir}/${e.name}` : e.name;
    if (e.isDir) await listMarkdown(source, rel, out);
    else if (e.name.endsWith('.md')) out.push(rel.slice(0, -3));
  }
  return out;
}

/**
 * Pages with `hidden: true` frontmatter are built even when no sidebar lists them (they are
 * reachable by URL, kept out of the sidebar, search and sitemap). Appends them as a hidden
 * group to the sidebar — or, with tabs, to the tab named by their `tab` frontmatter / `path`
 * prefix, else the first content tab. Returns the config unchanged when there are none.
 */
export async function appendHiddenPages(config, source) {
  if (!config) return config;
  const hasTabsList = Array.isArray(config.tabs) && config.tabs.length > 0;
  if (!hasTabsList && !Array.isArray(config.sidebar)) return config;
  const listed = new Set(collectIds(config.sidebar || []));
  if (hasTabsList) for (const t of config.tabs) if (t && Array.isArray(t.sidebar)) for (const id of collectIds(t.sidebar)) listed.add(id);
  const found = [];
  for (const id of await listMarkdown(source)) {
    if (listed.has(id)) continue;
    let fm = {};
    try { fm = parseFrontmatter(await source.read(`${id}.md`) || '').data || {}; } catch { continue; }
    if (isHiddenMeta(fm) && fm.draft !== true) found.push({ id, tab: typeof fm.tab === 'string' ? fm.tab : '' });
  }
  if (!found.length) return config;
  found.sort((a, b) => (a.id < b.id ? -1 : 1));
  if (!hasTabsList) {
    return { ...config, sidebar: [...(config.sidebar || []), { group: '', hidden: true, pages: found.map((f) => ({ id: f.id, hidden: true })) }] };
  }
  const tabs = config.tabs.map((t) => (t && !t.href ? { ...t, sidebar: Array.isArray(t.sidebar) ? [...t.sidebar] : [] } : t));
  const contentIdx = tabs.map((t, i) => (t && !t.href ? i : -1)).filter((i) => i >= 0);
  if (!contentIdx.length) return config;
  const labelOf = (t) => String(t.tab ?? t.label ?? t.title ?? t.name ?? '');
  const byTab = new Map();
  for (const f of found) {
    let idx = -1;
    if (f.tab) {
      const w = slugify(f.tab);
      idx = contentIdx.find((i) => slugify(tabs[i].id || labelOf(tabs[i])) === w || slugify(labelOf(tabs[i])) === w);
    }
    if (idx === undefined || idx < 0) {
      let best = -1;
      for (const i of contentIdx) {
        const p = normalizeDir(tabs[i].path);
        if (p && (f.id === p || f.id.startsWith(p + '/')) && (best < 0 || p.length > normalizeDir(tabs[best].path).length)) best = i;
      }
      idx = best;
    }
    if (idx < 0) idx = contentIdx[0];
    if (!byTab.has(idx)) byTab.set(idx, []);
    byTab.get(idx).push({ id: f.id, hidden: true });
  }
  for (const [idx, pages] of byTab) tabs[idx].sidebar.push({ group: '', hidden: true, pages });
  return { ...config, tabs };
}

/**
 * Expand config.sidebar using the docs directory (string path or a source).
 * Returns a new config object (the input is not mutated).
 */
export async function expandSidebar(config, docsDirOrSource, opts = {}) {
  if (!config || !hasAutogenerate(config.sidebar)) return config;
  const source = typeof docsDirOrSource === 'string' ? createFsSource(docsDirOrSource) : docsDirOrSource;
  const sidebar = await expandSidebarValue(config.sidebar, source, { siteName: config.name, ...opts });
  return { ...config, sidebar };
}

/**
 * Expand the main sidebar plus per-locale sidebars ("sidebar.<locale>" and
 * "sidebars.<locale>") against docs/ and docs.<locale>/ under cwd.
 */
export async function expandAllSidebars(config, cwd, opts = {}) {
  let out = await expandSidebar(config, path.join(cwd, 'docs'), opts);
  for (const key of Object.keys(config || {})) {
    const m = key.match(/^sidebar\.(.+)$/);
    if (m && hasAutogenerate(config[key])) {
      const source = createFsSource(path.join(cwd, `docs.${m[1]}`));
      out = { ...out, [key]: await expandSidebarValue(config[key], source, { siteName: config.name, ...opts }) };
    }
  }
  if (config?.sidebars && typeof config.sidebars === 'object') {
    for (const [locale, value] of Object.entries(config.sidebars)) {
      if (!hasAutogenerate(value)) continue;
      const source = createFsSource(path.join(cwd, `docs.${locale}`));
      out = { ...out, sidebars: { ...out.sidebars, [locale]: await expandSidebarValue(value, source, { siteName: config.name, ...opts }) } };
    }
  }
  if (Array.isArray(config?.tabs) && config.tabs.length) {
    if (hasTabAutogenerate(config.tabs)) {
      const source = createFsSource(path.join(cwd, 'docs'));
      out = { ...out, tabs: await expandTabsValue(config.tabs, source, { siteName: config.name, ...opts }) };
    }
  }
  if (out && (Array.isArray(out.sidebar) || (Array.isArray(out.tabs) && out.tabs.length))) {
    out = await appendHiddenPages(out, createFsSource(path.join(cwd, 'docs')));
  }
  if (Array.isArray(out?.tabs) && out.tabs.length) out = applyNavigation(out, opts);
  return out;
}

/** True if a docs-relative page id falls under an autogenerated directory of the raw sidebar. */
export function isAutogeneratedPage(sidebar, pageId) {
  if (sidebar === 'auto') return true;
  if (!Array.isArray(sidebar)) return false;
  const walk = (items) => items.some((it) => {
    if (!it || typeof it !== 'object') return false;
    if (it.autogenerate !== undefined) {
      const d = normalizeDirectory(typeof it.autogenerate === 'string' ? it.autogenerate : it.autogenerate?.directory);
      if (d === '' || (d && pageId.startsWith(d + '/'))) return true;
    }
    return Array.isArray(it.pages) && walk(it.pages);
  });
  return walk(sidebar);
}
